The rule staggers maintenance by scoring each available robot with its used work budget plus an opening-order offset derived from maintenance durations, so robots enter maintenance at different times while total workload stays balanced. It prioritizes the robot with the smallest such score, breaks ties toward later-opened robots to use new capacity, and prefers opening the gene-chosen type or an already-opened type with shorter maintenance when a new robot is required.

```python
def rule(ctx):
    types = ctx.types
    robots = ctx.robots
    n = len(robots)
    denom = float(max(1, n - 1))

    # Offset robots by opening order, scaled so the total lead is about one
    # maintenance duration.  This staggers maintenance windows.
    offset = {}
    cur = 0.0
    ordered = sorted(robots, key=lambda r: r.idx)
    for r in ordered:
        offset[r.idx] = cur
        p = types[r.type]
        if p is not None:
            cur += float(p["maintenance_time"]) / denom

    def score(r):
        p = types[r.type]
        if p is None:
            used = 0.0
        else:
            used = float(p["continue_max_work"]) - float(r.budget)
            if used < 0.0:
                used = 0.0
        return used + offset.get(r.idx, 0.0)

    # Best reuse option first; ties go to later-opened robots.
    avail_sorted = sorted(ctx.available, key=lambda r: (score(r), -r.idx))
    actions = [("reuse", r) for r in avail_sorted]

    # New-robot type preference.
    new_types = []
    gt = ctx.gene_type
    if 0 <= gt < len(ctx.left) and ctx.left[gt] > 0 and types[gt] is not None:
        new_types.append(gt)

    opened_count = {}
    for r in robots:
        opened_count[r.type] = opened_count.get(r.type, 0) + 1

    cand = []
    for k, left in enumerate(ctx.left):
        if left > 0 and k != gt:
            p = types[k]
            if p is None:
                continue
            cand.append((
                k,
                opened_count.get(k, 0),
                p["maintenance_time"],
                p["continue_max_work"]
            ))
    # Prefer already-opened types, then short maintenance, then large budget.
    cand.sort(key=lambda item: (-item[1], item[2], -item[3]))
    for k, _, _, _ in cand:
        new_types.append(k)

    for k in new_types:
        actions.append(("new", k))

    if not actions:
        fallback = gt if 0 <= gt < len(ctx.left) else 0
        actions.append(("new", fallback))

    return actions
```

The rule balances available robots using a combined load of duty count and duty hours (normalized by average duty length), with remaining budget as a tie-breaker; when a new robot is unavoidable, it opens the type that can supply the most estimated duty hours over the remaining horizon after accounting for work budget, maintenance, travel, and charging, using the gene-chosen type only as a tie-break.

```python
def rule(ctx):
    # Estimate total duty hours one new robot of type k can supply over the remaining horizon.
    def type_work(k):
        p = ctx.types[k]
        if p is None:
            return -1.0
        w = p['work_time']
        if w <= 0:
            w = 1e-9
        s = p['single_work_time']
        if s <= 0:
            s = 1e-9
        cmax = p['continue_max_work']
        if cmax < 0:
            cmax = 0.0
        dpc = int(cmax // s)
        if dpc < 1:
            dpc = 1
        time_duty = w + p['out_travel_time'] + p['return_travel_time'] + p['charge_time']
        if time_duty <= 0:
            time_duty = w
        maint = p['maintenance_time']
        if maint < 0:
            maint = 0.0
        work_phase = dpc * time_duty
        cycle = work_phase + maint
        H = ctx.remaining
        if H < 0:
            H = 0.0
        if cycle <= 0:
            return w * dpc
        full = int(H // cycle)
        rem = H - full * cycle
        work = full * dpc * w
        if rem > 0:
            d = int(rem // time_duty)
            if d > dpc:
                d = dpc
            if d == 0 and rem >= w:
                d = 1
            work += d * w
        if work <= 0:
            work = w
        return work

    # Preferred new-robot types: most productive per robot first.
    new_types = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            new_types.append(k)

    type_scores = {}
    for k in new_types:
        type_scores[k] = type_work(k)

    def new_key(k):
        return (-type_scores[k], 0 if k == ctx.gene_type else 1, k)

    new_types.sort(key=new_key)
    new_actions = [("new", k) for k in new_types]

    if not new_actions:
        if 0 <= ctx.gene_type < len(ctx.types) and ctx.types[ctx.gene_type] is not None:
            new_actions.append(("new", ctx.gene_type))

    if not ctx.available:
        return new_actions

    # Average duty length among opened robots, used to normalize duty hours.
    n_rob = len(ctx.robots)
    sum_count = 0
    sum_hours = 0.0
    for r in ctx.robots:
        sum_count += r.count
        sum_hours += r.hours

    if sum_count > 0:
        avg_duty = sum_hours / sum_count
    elif n_rob > 0:
        total_w = 0.0
        for r in ctx.robots:
            p = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
            total_w += p['work_time'] if p is not None else 10.0
        avg_duty = total_w / n_rob
    else:
        avg_duty = 10.0

    if avg_duty <= 0:
        avg_duty = 10.0

    def avail_key(r):
        p = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        d = p['work_time'] if p is not None else 10.0
        score = (r.count + 1.0) + (r.hours + d) / avg_duty
        return (score, -r.duties_left, -r.budget, r.idx)

    ordered = sorted(ctx.available, key=avail_key)
    return [("reuse", r) for r in ordered] + new_actions
```

The rule keeps the original balancing idea: it projects each available robot’s post-duty count and duty hours, scales hours by the current average duty length, and uses that combined load as the primary key. Ties prefer robots whose projected first maintenance is later, then opening order. When a new robot may be needed, it orders types by duty-length closeness to the existing average while prioritizing types with enough cycle capacity for the remaining need and using long-run capacity and remaining availability as tie-breakers.

```python
def rule(ctx):
    total_count = 0
    total_hours = 0.0
    for r in ctx.robots:
        total_count += r.count
        total_hours += r.hours

    if total_count > 0:
        avg_duty = total_hours / total_count
    else:
        vals = []
        for k in range(len(ctx.left)):
            if ctx.left[k] > 0 and ctx.types[k] is not None:
                vals.append(ctx.types[k]["work_time"])
        if vals:
            avg_duty = sum(vals) / len(vals)
        else:
            avg_duty = 10.0
    if avg_duty <= 0:
        avg_duty = 1.0

    scored = []
    for r in ctx.available:
        p = ctx.types[r.type]
        duty = p["work_time"] if p is not None else avg_duty
        proj_count = r.count + 1
        proj_hours = r.hours + duty
        load = proj_count + proj_hours / avg_duty

        if r.first_maint is not None:
            maint = r.first_maint
        else:
            if p is not None:
                cycle = duty + p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
                rem = r.duties_left
                if rem is None or rem < 1:
                    rem = 1
                maint = ctx.t + duty + p["return_travel_time"] + (rem - 1) * cycle
            else:
                maint = ctx.t + duty

        scored.append((load, -maint, r.idx, r))

    scored.sort(key=lambda x: (x[0], x[1], x[2]))
    actions = [("reuse", x[3]) for x in scored]

    capacity = ctx.capacity
    need = ctx.remaining - capacity
    if need < 0:
        need = 0.0

    candidates = []
    for k in range(len(ctx.left)):
        if ctx.left[k] <= 0:
            continue
        p = ctx.types[k]
        if p is None:
            continue

        duty = p["work_time"]
        single = p["single_work_time"]
        if single > 0:
            duties_cycle = p["continue_max_work"] / single
        else:
            duties_cycle = 1.0

        cap_now = duty * duties_cycle
        travel = p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
        cycle_time = duties_cycle * (duty + travel) + p["maintenance_time"]
        long_cap = cap_now / cycle_time if cycle_time > 0 else cap_now
        close = abs(duty - avg_duty)
        candidates.append((k, close, cap_now, long_cap, ctx.left[k]))

    if need > 0:
        enough = [c for c in candidates if c[2] >= need]
        rest = [c for c in candidates if c[2] < need]
        enough.sort(key=lambda c: (c[1], -c[3], -c[4], c[0]))
        rest.sort(key=lambda c: (-c[2], c[1], -c[3], -c[4], c[0]))
        candidates = enough + rest
    else:
        candidates.sort(key=lambda c: (c[1], -c[3], -c[4], c[0]))

    if len(actions) == 0 or need > 0:
        for c in candidates:
            actions.append(("new", c[0]))

    if len(actions) == 0:
        actions.append(("new", ctx.gene_type))

    return actions
```

The rule keeps the default choice strongly balanced, so the no-deviation roster minimizes duty-count/hour imbalance, but it adds a careful maintenance-urgency layer: when no robot is already in maintenance it lets a robot near its budget limit go slightly earlier, and when one robot is down it penalizes sending another near-maintenance robot, keeping it as a buffer. The remaining reuse alternatives are reordered separately to expose useful deviations—especially the robot closest to maintenance when no maintenance is active—while new types are chosen by remaining work capacity with small penalties for overshoot and imbalance.

```python
def rule(ctx):
    n_rob = len(ctx.robots)
    sum_count = 0
    sum_hours = 0.0
    for r in ctx.robots:
        sum_count += r.count
        sum_hours += r.hours

    mean_count = sum_count / n_rob if n_rob > 0 else 0.0
    mean_hours = sum_hours / n_rob if n_rob > 0 else 0.0

    if sum_count > 0:
        avg_duty = sum_hours / sum_count
    elif n_rob > 0:
        total_w = 0.0
        for r in ctx.robots:
            p = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
            total_w += p['work_time'] if p is not None else 10.0
        avg_duty = total_w / n_rob
    else:
        avg_duty = 10.0
    if avg_duty <= 0:
        avg_duty = 10.0

    down_maint = 0
    for r in ctx.robots:
        if r.ready > ctx.t and (r.duties_left <= 0 or r.budget <= 0):
            down_maint += 1

    def type_work(k):
        p = ctx.types[k]
        if p is None:
            return -1e9
        w = p['work_time']
        if w <= 0:
            w = 1e-6
        s = p['single_work_time']
        if s <= 0:
            s = 1e-6
        cmax = p['continue_max_work']
        if cmax < 0:
            cmax = 0.0
        dpc = int(cmax // s)
        if dpc < 1:
            dpc = 1
        time_duty = w + p['out_travel_time'] + p['return_travel_time'] + p['charge_time']
        if time_duty <= 0:
            time_duty = w
        maint = p['maintenance_time']
        if maint < 0:
            maint = 0.0
        work_phase = dpc * time_duty
        cycle = work_phase + maint

        H = ctx.remaining
        if H < 0:
            H = 0.0

        if cycle <= 0:
            work = w * dpc
        else:
            full = int(H // cycle)
            rem = H - full * cycle
            work = full * dpc * w
            if rem > 0:
                d = int(rem // time_duty)
                if d > dpc:
                    d = dpc
                if d == 0 and rem >= w:
                    d = 1
                work += d * w
            if work <= 0:
                work = w

        usable = work
        if H > 0:
            if usable > H:
                usable = H - 0.05 * (usable - H)
            if w > H:
                usable -= 0.2 * (w - H)

        if n_rob > 0:
            usable -= 0.02 * abs(work - mean_hours)
            est_count = work / w
            usable -= 0.02 * abs(est_count - mean_count)

        return usable

    new_types = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            new_types.append(k)

    type_scores = {}
    for k in new_types:
        type_scores[k] = type_work(k)

    if 0 <= ctx.gene_type < len(ctx.types) and ctx.gene_type in type_scores:
        type_scores[ctx.gene_type] += 0.05

    def new_key(k):
        return (-type_scores[k], 0 if k == ctx.gene_type else 1, k)

    new_types.sort(key=new_key)
    new_actions = [("new", k) for k in new_types]

    if not new_actions:
        if 0 <= ctx.gene_type < len(ctx.types) and ctx.types[ctx.gene_type] is not None:
            new_actions.append(("new", ctx.gene_type))

    if not ctx.available:
        return new_actions

    scored = []
    for r in ctx.available:
        p = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        w = p['work_time'] if p is not None else avg_duty
        if w <= 0:
            w = avg_duty

        base = (r.count + 1.0) + (r.hours + w) / avg_duty
        dl = r.duties_left

        maint_def = 0.0
        if down_maint == 0:
            if dl <= 1:
                bonus = 1.2
                if r.count > mean_count + 1.0:
                    bonus = 0.6
                if r.count > mean_count + 2.0:
                    bonus = 0.15
                maint_def -= bonus
            elif dl <= 2:
                maint_def -= 0.3
            elif dl <= 3:
                maint_def -= 0.05
        else:
            if dl <= 1:
                maint_def += 0.9
            elif dl <= 2:
                maint_def += 0.25
            elif dl > 3:
                maint_def -= 0.05

        default_val = base + maint_def

        maint_alt = 0.0
        if down_maint == 0:
            maint_alt = 0.6 * dl
            if dl <= 1:
                maint_alt -= 0.8
            elif dl <= 2:
                maint_alt -= 0.2
        else:
            if dl <= 1:
                maint_alt += 0.6
            elif dl > 3:
                maint_alt -= 0.1

        alt_val = base + maint_alt
        scored.append((default_val, alt_val, r))

    default_robot = min(
        scored,
        key=lambda x: (x[0], -x[2].duties_left, -x[2].budget, x[2].idx)
    )[2]

    default_idx = default_robot.idx
    rest = [item for item in scored if item[2].idx != default_idx]
    rest.sort(key=lambda x: (x[1], x[2].duties_left, x[2].idx))

    ordered = [default_robot] + [item[2] for item in rest]

    return [("reuse", r) for r in ordered] + new_actions
```

The rule uses an adaptive maintenance-batching idea: it estimates how many robots must be concurrently available for continuous coverage, allows only the remaining robots to enter maintenance together, and assigns staggered maintenance windows only as far apart as needed for the previous batch to return. This reduces first-maintenance spread compared with uniform over-staggering while protecting coverage. The default choice among available robots minimizes a type-normalized work-progress score plus its batch delay, and new-robot types are chosen by preferring already-opened types, then horizon capacity, then the genome’s type.

```python
def rule(ctx):
    types = ctx.types
    robots = ctx.robots
    n = len(robots)
    H = ctx.remaining
    if H < 0.0:
        H = 0.0

    # Required number of concurrently available robots.
    k_req = 1
    counted = False
    for r in robots:
        p = types[r.type] if 0 <= r.type < len(types) else None
        if p is None:
            continue
        counted = True
        d = float(p['work_time'])
        if d <= 0.0:
            d = 1.0
        cyc = d + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
        if cyc <= 0.0:
            cyc = d
        ratio = cyc / d
        req = int(ratio)
        if ratio > req + 1e-9:
            req += 1
        if req > k_req:
            k_req = req

    if not counted:
        for p in types:
            if p is None:
                continue
            d = float(p['work_time'])
            if d <= 0.0:
                d = 1.0
            cyc = d + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
            if cyc <= 0.0:
                cyc = d
            ratio = cyc / d
            req = int(ratio)
            if ratio > req + 1e-9:
                req += 1
            if req > k_req:
                k_req = req

    # Maximum number of robots that may be in maintenance at once.
    if n <= 1:
        m = 1
    else:
        m = n - k_req
        if m < 1:
            m = 1
        if m > n - 1:
            m = n - 1

    active_after = n - m
    if active_after < 1:
        active_after = 1

    # Rank and batch maintenance windows by opening order.
    order = sorted(robots, key=lambda r: r.idx)
    batch_of = {}
    batch_max = {}
    for i, r in enumerate(order):
        b = i // m
        batch_of[r.idx] = b
        p = types[r.type] if 0 <= r.type < len(types) else None
        M = float(p['maintenance_time']) if p is not None else 0.0
        if b not in batch_max or M > batch_max[b]:
            batch_max[b] = M

    max_b = (n - 1) // m if n > 0 else 0
    batch_start = []
    cum = 0.0
    for b in range(max_b + 1):
        batch_start.append(cum)
        cum += batch_max.get(b, 0.0)

    # Score available robots: least normalized work plus staggered batch delay.
    avail_scored = []
    for r in ctx.available:
        p = types[r.type] if 0 <= r.type < len(types) else None
        if p is None:
            key = (1e18, r.count, r.hours, -r.idx)
        else:
            d = float(p['work_time'])
            s = float(p['single_work_time'])
            if s <= 0.0:
                s = d if d > 0.0 else 1.0
            cyc = d + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
            if cyc <= 0.0:
                cyc = s
            cmax = float(p['continue_max_work'])
            used = cmax - float(r.budget)
            if used < 0.0:
                used = 0.0
            if used > cmax:
                used = cmax
            b = batch_of.get(r.idx, 0)
            ds = batch_start[b] if b < len(batch_start) else 0.0
            if ds > H:
                ds = H
            offset_work = ds * s / (active_after * cyc)
            score = used + offset_work
            key = (score, r.count, r.hours, -r.idx)
        avail_scored.append((key, r))
    avail_scored.sort(key=lambda item: item[0])
    actions = [("reuse", r) for _, r in avail_scored]

    # New-robot type selection.
    opened_count = {}
    for r in robots:
        opened_count[r.type] = opened_count.get(r.type, 0) + 1

    def type_capacity(k):
        p = types[k]
        if p is None:
            return -1.0
        w = float(p['work_time'])
        if w <= 0.0:
            w = 1.0
        s = float(p['single_work_time'])
        if s <= 0.0:
            s = w
        cmax = float(p['continue_max_work'])
        if cmax < 0.0:
            cmax = 0.0
        dpc = int(cmax // s) if s > 0.0 else 1
        if dpc < 1:
            dpc = 1
        duty_cycle = w + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
        if duty_cycle <= 0.0:
            duty_cycle = w
        maint = float(p['maintenance_time'])
        if maint < 0.0:
            maint = 0.0
        work_phase = dpc * duty_cycle
        cycle = work_phase + maint
        H2 = ctx.remaining
        if H2 < 0.0:
            H2 = 0.0
        if cycle <= 0.0:
            return w * dpc
        full = int(H2 // cycle)
        rem = H2 - full * cycle
        work = full * dpc * w
        if rem > 0.0:
            d = int(rem // duty_cycle)
            if d > dpc:
                d = dpc
            if d == 0 and rem >= w:
                d = 1
            work += d * w
        if work <= 0.0:
            work = w
        return work

    cand = []
    for k, left in enumerate(ctx.left):
        if left > 0 and k < len(types) and types[k] is not None:
            p = types[k]
            cap = type_capacity(k)
            opened = opened_count.get(k, 0)
            key = (0 if opened > 0 else 1,
                   -cap,
                   0 if k == ctx.gene_type else 1,
                   float(p['maintenance_time']),
                   -float(p['continue_max_work']))
            cand.append((key, k))
    cand.sort(key=lambda item: item[0])
    for _, k in cand:
        actions.append(("new", k))

    if not actions:
        k = ctx.gene_type
        if not (0 <= k < len(ctx.types) and ctx.left[k] > 0 and ctx.types[k] is not None):
            k = 0
            for j, left in enumerate(ctx.left):
                if left > 0 and j < len(ctx.types) and ctx.types[j] is not None:
                    k = j
                    break
        actions.append(("new", k))

    return actions
```

Combines Rule 1’s balanced reuse scoring and capacity-gated new-robot alternatives with Rule 2’s full-horizon productivity estimate for choosing new robot types, while adding maintenance/duties-left tie-breakers to better preserve balance and avoid unnecessary resource openings.

```python
def rule(ctx):
    def type_work(k):
        if k < 0 or k >= len(ctx.types):
            return -1.0
        p = ctx.types[k]
        if p is None:
            return -1.0

        w = p["work_time"]
        if w <= 0:
            w = 1e-9

        s = p["single_work_time"]
        cmax = p["continue_max_work"]
        if cmax < 0:
            cmax = 0.0

        if s > 0:
            dpc = int(cmax // s)
        else:
            dpc = 1
        if dpc < 1:
            dpc = 1

        time_duty = w + p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
        if time_duty <= 0:
            time_duty = w

        maint = p["maintenance_time"]
        if maint < 0:
            maint = 0.0

        cycle = dpc * time_duty + maint
        H = ctx.remaining
        if H < 0:
            H = 0.0

        if cycle <= 0:
            return w * dpc

        full = int(H // cycle)
        rem = H - full * cycle
        work = full * dpc * w

        if rem > 0:
            d = int(rem // time_duty)
            if d > dpc:
                d = dpc
            if d == 0 and rem >= w:
                d = 1
            work += d * w

        if work <= 0:
            work = w
        return work

    total_count = 0
    total_hours = 0.0
    for r in ctx.robots:
        total_count += r.count
        total_hours += r.hours

    if total_count > 0:
        avg_duty = total_hours / total_count
    else:
        vals = []
        for r in ctx.robots:
            if 0 <= r.type < len(ctx.types):
                p = ctx.types[r.type]
                if p is not None and p["work_time"] > 0:
                    vals.append(p["work_time"])
        if not vals:
            for k in range(len(ctx.types)):
                if ctx.left[k] > 0 and ctx.types[k] is not None:
                    vals.append(ctx.types[k]["work_time"])
        if vals:
            avg_duty = sum(vals) / len(vals)
        else:
            avg_duty = 10.0

    if avg_duty <= 0:
        avg_duty = 1.0

    scored = []
    for r in ctx.available:
        p = ctx.types[r.type] if 0 <= r.type < len(ctx.types) else None
        duty = p["work_time"] if p is not None else avg_duty
        if duty <= 0:
            duty = avg_duty

        proj_count = r.count + 1
        proj_hours = r.hours + duty
        load = proj_count + proj_hours / avg_duty

        if r.first_maint is not None:
            maint = r.first_maint
        else:
            if p is not None:
                cycle = duty + p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
                remd = r.duties_left
