The rule ranks available robots by a balanced post-assignment load: duty count plus normalized duty hours (using 10 h as the reference duty), so mixed 6/8/10/12 h types are not unfairly preferred or overloaded. It also penalizes choices that would exceed the horizon or leave an uncoverable remainder, and uses remaining maintenance budget plus lower travel/charge overhead as tie-breakers. The genome-selected new-robot type is kept first when valid, with other feasible types appended by maintenance efficiency and horizon fit.

```python
def rule(ctx):
    rem = ctx.remaining
    types = ctx.types
    left = ctx.left

    opened = set()
    for r in ctx.robots:
        opened.add(r.type)

    min_w = 10.0
    for k, tp in enumerate(types):
        if tp is not None and (left[k] > 0 or k in opened):
            w = tp['work_time']
            if w < min_w:
                min_w = w
    if min_w <= 1e-9:
        min_w = 1.0

    scored = []
    for r in ctx.available:
        tp = types[r.type] if 0 <= r.type < len(types) else None
        if tp is not None:
            w = tp['work_time']
            overhead = tp['out_travel_time'] + tp['return_travel_time'] + tp['charge_time']
        else:
            w = 10.0
            overhead = 0.0

        # Balance the post-assignment duty count and duty hours.
        load = r.count + (r.hours + w) / 10.0
        penalty = 0.0

        if w > rem + 1e-9:
            penalty += 1000.0 + (w - rem)
        else:
            rem2 = rem - w
            if rem2 > 1e-9:
                if rem2 < min_w - 1e-9:
                    penalty += 1000.0 + (min_w - rem2)
            else:
                load -= 10.0  # exact horizon fit

        scored.append((load + penalty, -r.duties_left, overhead, r.idx, r))

    scored.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    actions = [("reuse", x[4]) for x in scored]

    cand = []
    for k, tp in enumerate(types):
        if tp is None or left[k] <= 0:
            continue

        w = tp['work_time']
        single = tp['single_work_time']
        K = tp['continue_max_work'] / single if single > 1e-9 else 999.0
        overhead = tp['out_travel_time'] + tp['return_travel_time'] + tp['charge_time']
        util = w / (w + overhead + 1e-9)

        score = K * 10.0 + util * 100.0 - tp['maintenance_time'] * 0.1

        if w > rem + 1e-9:
            score -= 1000.0 + (w - rem)
        else:
            rem2 = rem - w
            if rem2 > 1e-9:
                if rem2 < min_w - 1e-9:
                    score -= 1000.0 + (min_w - rem2)
            else:
                score += 10.0  # exact horizon fit

        cand.append((score, k))

    cand.sort(key=lambda x: (-x[0], x[1]))

    gene = ctx.gene_type
    if 0 <= gene < len(types) and types[gene] is not None and left[gene] > 0:
        actions.append(("new", gene))
        for _, k in cand:
            if k != gene:
                actions.append(("new", k))
    else:
        for _, k in cand:
            actions.append(("new", k))
        if not cand:
            actions.append(("new", gene))

    return actions
