def rule(ctx):
    types = ctx.types
    t = ctx.t
    rem = ctx.remaining
    if rem < 0.0:
        rem = 0.0
    robots = ctx.robots
    n_robots = len(robots)

    def type_ratio(p):
        w = float(p['work_time'])
        if w <= 0.0:
            w = 1.0
        cyc = w + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
        if cyc <= 0.0:
            cyc = w
        ratio = cyc / w
        req = int(ratio)
        if ratio > req + 1e-9:
            req += 1
        if req < 1:
            req = 1
        return req

    def type_capacity(p, H):
        w = float(p['work_time'])
        if w <= 0.0:
            w = 1.0
        s = float(p['single_work_time'])
        if s <= 0.0:
            s = w
        cmax = float(p['continue_max_work'])
        if cmax < 0.0:
            cmax = 0.0
        if s > 0.0:
            dpc = int(cmax // s)
        else:
            dpc = 1
        if dpc < 1:
            dpc = 1
        duty_cycle = w + float(p['out_travel_time']) + float(p['return_travel_time']) + float(p['charge_time'])
        if duty_cycle <= 0.0:
            duty_cycle = w
        maint = float(p['maintenance_time'])
        if maint < 0.0:
            maint = 0.0
        work_phase = dpc * duty_cycle
        cycle = work_phase + maint
        if cycle <= 0.0:
            return w * dpc
        full = int(H // cycle)
        remH = H - full * cycle
        work = full * dpc * w
        if remH > 0.0:
            d = int(remH // duty_cycle)
            if d > dpc:
                d = dpc
            if d == 0 and remH >= w:
                d = 1
            work += d * w
        if work <= 0.0:
            work = w
        return work

    opened_types = set()
    for r in robots:
        opened_types.add(r.type)

    if opened_types:
        k_req = 1
        for k in opened_types:
            p = types[k] if 0 <= k < len(types) else None
            if p is not None:
                req = type_ratio(p)
                if req > k_req:
                    k_req = req
    else:
        best_ratio = None
        for k, p in enumerate(types):
            if p is None or ctx.left[k] <= 0:
                continue
            req = type_ratio(p)
            if best_ratio is None or req < best_ratio:
                best_ratio = req
        k_req = best_ratio if best_ratio is not None else 1

    active = 0
    for r in robots:
        if r.budget > 1e-9:
            active += 1
    maint = n_robots - active

    def choose_new_type():
        best_k = None
        best_key = None
        for k, p in enumerate(types):
            if p is None or ctx.left[k] <= 0:
                continue
            req = type_ratio(p)
            inc = 1 if req > k_req else 0
            opened = 0 if k in opened_types else 1
            cap = type_capacity(p, rem)
            key = (inc, opened, -cap, req,
                   float(p['maintenance_time']),
                   -float(p['continue_max_work']),
                   0 if k == ctx.gene_type else 1,
                   k)
            if best_key is None or key < best_key:
                best_key = key
                best_k = k
        return best_k

    can_open = False
    for k, p in enumerate(types):
        if p is not None and ctx.left[k] > 0:
            can_open = True
            break

    new_k = None
    if can_open and ctx.capacity < rem - 1e-9:
        new_k = choose_new_type()

    sum_w = 0.0
    cnt_w = 0
    for k, p in enumerate(types):
        if p is not None:
            sum_w += float(p['work_time'])
            cnt_w += 1
    avg_w = sum_w / cnt_w if cnt_w > 0 else 10.0
    if avg_w <= 0.0:
        avg_w = 10.0

    avail = list(ctx.available)
    scored = []
    for r in avail:
        p = types[r.type] if 0 <= r.type < len(types) else None
        if p is None:
            key = (9, r.count, r.hours, r.idx)
            scored.append((key, r))
            continue
        w = float(p['work_time'])
        s = float(p['single_work_time'])
        if s <= 0.0:
            s = w if w > 0.0 else 1.0
        triggers = (r.duties_left <= 1) or (r.budget <= s + 1e-9)
        maint_time = float(p['maintenance_time'])
        charge = float(p['charge_time'])
        out_t = float(p['out_travel_time'])
        ret_t = float(p['return_travel_time'])
        can_return = rem > (maint_time + charge + out_t + w + ret_t)
        if active > k_req and can_return:
            key = (0 if triggers else 1,
                   r.duties_left,
                   -r.count,
                   -r.hours,
                   maint_time,
                   r.idx)
        elif maint > 0:
            key = (0 if not triggers else 1,
                   -r.duties_left,
                   r.count,
                   r.hours,
                   maint_time,
                   r.idx)
        else:
            load = r.count + r.hours / avg_w
            key = (0 if not triggers else 1,
                   load,
                   r.duties_left,
                   maint_time,
                   r.idx)
        scored.append((key, r))

    scored.sort(key=lambda item: item[0])
    actions = [("reuse", r) for _, r in scored]

    if new_k is not None:
        actions.insert(0, ("new", new_k))
    else:
        best_new = choose_new_type()
        if best_new is not None:
            actions.append(("new", best_new))
        else:
            gt = ctx.gene_type
            if gt is None or not (0 <= gt < len(types)) or types[gt] is None or ctx.left[gt] <= 0:
                gt = 0
                for k, p in enumerate(types):
                    if p is not None and ctx.left[k] > 0:
                        gt = k
                        break
            actions.append(("new", gt))

    if not actions:
        gt = ctx.gene_type if ctx.gene_type is not None else 0
        actions.append(("new", gt))

    return actions
