        else:
            w = 10.0
            overhead = 0.0

        if w <= eps:
            w = 1.0

        load = r.count + (r.hours + w) / avg_w
        penalty = 0.0

        if w > rem + eps:
            penalty += 1000.0 + (w - rem) * 2.0
        else:
            rem2 = rem - w
            if rem2 > eps:
                if rem2 < min_w - eps:
                    penalty += 1000.0 + (min_w - rem2) * 2.0
            else:
                load -= 10.0

        if tight:
            if busy_remaining > eps:
                can_cover = r.duties_left * w + eps >= busy_remaining
                if can_cover:
                    penalty += 1.5 * r.duties_left
                else:
                    penalty += 500.0 + (busy_remaining - r.duties_left * w)
            else:
                penalty += 2.5 * r.duties_left

        scored.append((load + penalty, -r.duties_left, overhead, r.idx, r))

    scored.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    actions = [("reuse", x[4]) for x in scored]

    cand = []
    for k, tp in enumerate(types):
        if tp is None or left[k] <= 0:
            continue

        w = tp['work_time']
        if w <= eps:
            w = 1.0

        single = tp['single_work_time']
        if single > eps:
            Kf = tp['continue_max_work'] / single
            K = int(Kf + 1e-9)
            if K < 1:
                K = 1
        else:
            K = 1000

        out = tp['out_travel_time']
        ret = tp['return_travel_time']
        charge = tp['charge_time']
        maint = tp['maintenance_time']

        per_duty = w + out + ret + charge
        if per_duty < w + 1e-9:
            per_duty = w

        if rem <= eps:
            duty_frac = 0.0
        elif rem <= K * w:
            duty_frac = w / per_duty
        else:
            cycle_time = K * per_duty + maint
            duty_frac = (K * w) / cycle_time if cycle_time > eps else 0.0

        score = duty_frac * 100.0

        if rem <= eps:
            cap_hours = 0.0
        else:
            first = int(rem / per_duty + 1e-9)
            if first > K:
                first = K
            if first < 0:
                first = 0
            cap_hours = first * w

            if first == K and rem > K * per_duty + maint:
                rem2 = rem - K * per_duty - maint
                cycle_time = K * per_duty + maint
                full = int(rem2 / cycle_time + 1e-9)
