                rem3 = rem2 - full * cycle_time
                if rem3 > 0:
                    extra = int(rem3 / per_duty + 1e-9)
                    if extra > K:
                        extra = K
                    cap_hours += extra * w

        if rem > eps:
            score += min(cap_hours / rem, 2.0) * 20.0

        if w > rem + eps:
            score -= 1000.0 + (w - rem) * 2.0
        else:
            rem2 = rem - w
            if rem2 > eps:
                if rem2 < min_w - eps:
                    score -= 1000.0 + (min_w - rem2) * 2.0
            else:
                score += 10.0

        cand.append((score, k))

    cand.sort(key=lambda x: (-x[0], x[1]))
    new_order = [k for _, k in cand]

    gene = ctx.gene_type
    if 0 <= gene < len(types) and types[gene] is not None and left[gene] > 0:
        gs = None
        best = None
        for s, k in cand:
