```python
def rule(ctx):
    min_L = None
    total_duty = 0.0
    n_types = 0
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None:
            Lk = ctx.types[k]["work_time"]
            total_duty += Lk
            n_types += 1
            if min_L is None or Lk < min_L:
                min_L = Lk
    if min_L is None:
        min_L = 0
    avg_duty = total_duty / n_types if n_types > 0 else 10.0

    def type_key(k):
        typ = ctx.types[k]
        L = typ["work_time"]
        over = L - ctx.remaining if L > ctx.remaining else 0
        rem_after = ctx.remaining - L
        bad_res = 1 if rem_after > 0 and rem_after < min_L else 0
        cycle = typ["out_travel_time"] + typ["return_travel_time"] + typ["charge_time"]
        single = typ["single_work_time"]
        cap = typ["continue_max_work"] / (single if single > 0 else 1.0)
        total_time = cap * (L + cycle) + typ["maintenance_time"]
        eff = (cap * L) / total_time if total_time > 0 else 0.0
        return (over, bad_res, -eff, typ["maintenance_time"], -L, k)

    def robot_key(r):
        typ = ctx.types[r.type]
        L = typ["work_time"]
        over = L - ctx.remaining if L > ctx.remaining else 0
        rem_after = ctx.remaining - L
        bad_res = 1 if rem_after > 0 and rem_after < min_L else 0
        load = r.count * avg_duty + r.hours + L
        cycle = typ["out_travel_time"] + typ["return_travel_time"] + typ["charge_time"]
        return (over, bad_res, load, -r.duties_left, -cycle, r.ready, r.idx)

    available = ctx.available
    if not available:
        candidates = []
        for k in range(len(ctx.types)):
            if ctx.types[k] is not None and ctx.left[k] > 0:
                candidates.append(type_key(k))
        if candidates:
            candidates.sort()
            new_order = [("new", k) for (_, _, _, _, _, k) in candidates]
            if 0 <= ctx.gene_type < len(ctx.types) and ctx.types[ctx.gene_type] is not None and ctx.left[ctx.gene_type] > 0:
                first_k = new_order[0][1]
                if ctx.gene_type != first_k:
                    new_order.insert(1, ("new", ctx.gene_type))
            seen = set()
            unique = []
            for a in new_order:
                if a[1] not in seen:
                    seen.add(a[1])
                    unique.append(a)
            return unique
        else:
            return [("new", ctx.gene_type)]

    sorted_av = sorted(available, key=robot_key)
    primary = sorted_av[0]

    alt = None
    alt_val = None
    for r in available:
        if r is primary:
            continue
        typ = ctx.types[r.type]
        L = typ["work_time"]
        over = L - ctx.remaining if L > ctx.remaining else 0
        rem_after = ctx.remaining - L
        bad_res = 1 if rem_after > 0 and rem_after < min_L else 0
        load = r.count * avg_duty + r.hours + L
        val = (over, bad_res, r.duties_left, load, r.idx)
        if alt is None or val < alt_val:
            alt = r
            alt_val = val

    actions = [("reuse", primary)]
    if alt is not None:
        actions.append(("reuse", alt))
    for r in sorted_av:
        if r is not primary and r is not alt:
            actions.append(("reuse", r))

    type_candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            type_candidates.append(type_key(k))
    if type_candidates:
        type_candidates.sort()
        new_actions = [("new", k) for (_, _, _, _, _, k) in type_candidates]
        if 0 <= ctx.gene_type < len(ctx.types) and ctx.types[ctx.gene_type] is not None and ctx.left[ctx.gene_type] > 0:
            first_k = new_actions[0][1]
            if ctx.gene_type != first_k:
