The improved rule keeps the baseline’s count-balancing behavior for uniform-duty instances, but adds a maintenance-capacity heuristic: when remaining capacity is short and multiple robots are available, it prefers robots closer to maintenance so their maintenance can be triggered earlier and their budget refreshed. For mixed-duty instances it uses a composite load combining duty count and duty hours, with a slight bias toward larger work-time robots to reduce the number of shifts and hence tool usage. New-robot type preferences respect the genome’s chosen type first, then fall back to types with larger work-time and lower maintenance overhead.

```python
def rule(ctx):
    def get_w(r):
        p = ctx.types[r.type]
        if p is None:
            return 10.0
        return p.get("work_time", 10.0)

    # Check whether opened robots have mixed duty lengths.
    ws = []
    for r in ctx.robots:
        p = ctx.types[r.type]
        if p is not None:
            ws.append(p.get("work_time", 10.0))
    mixed = False
    if ws:
        w0 = ws[0]
        for w in ws:
            if abs(w - w0) > 1e-6:
                mixed = True
                break

    # Is the remaining horizon likely under-covered?
    short_cap = False
    try:
        short_cap = ctx.capacity < ctx.remaining
    except:
        short_cap = False

    avail = list(ctx.available)
    n = len(ctx.robots)
    if n > 0:
        mean_count = sum(r.count for r in ctx.robots) / n
        mean_hours = sum(r.hours for r in ctx.robots) / n
    else:
        mean_count = 0.0
        mean_hours = 0.0

    if mean_count > 0.1:
        target_w = mean_hours / mean_count
    else:
        target_w = 10.0

    def key(r):
        p = ctx.types[r.type]
        w = p.get("work_time", 10.0) if p is not None else 10.0

        if not mixed:
            # Uniform duty lengths: balance count.
            # Normally prefer fresher robots (higher duties_left).
            # If capacity is short and we have alternatives, prefer robots
            # closer to maintenance to trigger a refresh sooner.
            if short_cap and len(avail) >= 2:
                return (r.count + 0.2 * r.duties_left, r.count, r.idx)
            else:
                return (r.count, -r.duties_left, r.idx)
        else:
            # Mixed duty lengths: balance count and hours, with a slight
            # preference for larger work_time to reduce shift/tool count.
            score = r.count + r.hours / (target_w + 1e-9) - 0.2 * w
            if short_cap:
                score += 0.2 * r.duties_left
            else:
                score -= 0.01 * r.duties_left
            return (score, r.count, r.idx)

    sorted_avail = sorted(avail, key=key)
    actions = [("reuse", r) for r in sorted_avail]

    # Rank new robot types. Keep the genome-chosen type first if possible.
    type_candidates = []
    for k, p in enumerate(ctx.types):
        if p is None:
            continue
        if ctx.left[k] <= 0:
            continue
        w = p.get("work_time", 10.0)
        mt = p.get("maintenance_time", 100.0)
        cmw = p.get("continue_max_work", 1.0)
        swt = p.get("single_work_time", 1.0)
        duties_per_maint = cmw / swt if swt > 0 else 0.0
        type_candidates.append((-w, mt, -duties_per_maint, k))
    type_candidates.sort()

    new_actions = []
    gene = ctx.gene_type
    if 0 <= gene < len(ctx.types) and ctx.types[gene] is not None and ctx.left[gene] > 0:
        new_actions.append(("new", gene))
    for _, _, _, k in type_candidates:
        if k != gene:
            new_actions.append(("new", k))
    if not new_actions:
        new_actions.append(("new", gene))

    actions.extend(new_actions)
    return actions
```

