The new rule uses horizon-aware maintenance pacing: it detects active maintenance and either deliberately triggers the next maintenance when it is safe (long horizon, no active maintenance), or avoids triggering and uses fresher robots to preserve capacity (active maintenance or near horizon end). It ties maintenance choices by shortest maintenance time to clear the queue faster, and uses a combined count/hours load metric for balance. New robot types are ranked by duties per maintenance and cycle overhead.

```python
def rule(ctx):
    t = ctx.t
    remaining = ctx.remaining
    types = ctx.types
    robots = ctx.robots
    avail = ctx.available
    gene = ctx.gene_type

    total_wt = 0.0
    cnt_types = 0
    max_maint = 0.0
    for typ in types:
        if typ is not None:
            total_wt += typ["work_time"]
            cnt_types += 1
            if typ["maintenance_time"] > max_maint:
                max_maint = typ["maintenance_time"]
    avg_wt = total_wt / cnt_types if cnt_types > 0 else 10.0

    active_maint = 0
    for r in robots:
        if r.ready > t:
            if r.duties_left <= 0:
                active_maint += 1
            else:
                typ = types[r.type] if r.type < len(types) else None
                if typ is not None:
                    normal = typ["charge_time"] + typ["out_travel_time"] + typ["return_travel_time"] + 5.0
                    if r.ready > t + normal:
                        active_maint += 1
                else:
                    if r.ready > t + 10.0:
                        active_maint += 1

    near_end = remaining < max_maint + 10.0

    def robot_key(r):
        typ = types[r.type] if r.type < len(types) else None
        load = r.count + r.hours / avg_wt if avg_wt > 0 else r.count
        triggers = r.duties_left <= 1
        mtime = typ["maintenance_time"] if (typ is not None and triggers) else 0.0

        if near_end:
            return (1 if triggers else 0, mtime, load)
        else:
            if active_maint > 0:
                return (1 if triggers else 0, -r.duties_left, mtime, load)
            else:
                if triggers:
                    return (0, r.duties_left, mtime, load)
                else:
                    return (0, r.duties_left, 0.0, load)

    sorted_avail = sorted(avail, key=robot_key)
    actions = [("reuse", r) for r in sorted_avail]

    new_list = []
    if gene is not None and 0 <= gene < len(types) and types[gene] is not None and ctx.left[gene] > 0:
        new_list.append(gene)

    type_scores = []
    for k in range(len(types)):
        typ = types[k]
        if typ is None or ctx.left[k] <= 0 or k == gene:
            continue
        sw = typ["single_work_time"]
        eff = typ["continue_max_work"] / sw if sw > 0 else 0.0
        score = -eff + typ["maintenance_time"] / 100.0 + typ["charge_time"] / 20.0
        score += (typ["out_travel_time"] + typ["return_travel_time"]) / 50.0
        type_scores.append((score, k))

    type_scores.sort(key=lambda x: (x[0], x[1]))
    for score, k in type_scores:
        new_list.append(k)

    if not new_list:
        for k in range(len(types)):
            if types[k] is not None and ctx.left[k] > 0:
                new_list.append(k)

    for k in new_list:
        actions.append(("new", k))

    if actions:
        return actions
    if gene is not None and 0 <= gene < len(types) and types[gene] is not None:
        return [("new", gene)]
    for k in range(len(types)):
        if types[k] is not None:
            return [("new", k)]
    return [("new", 0)]
