The combined rule keeps Rule 2’s balanced reuse ordering and sustainable new-type scoring, but adds Rule 1’s awareness of already-down robots: when maintenance is already causing a shortage, it avoids sending robots that would immediately trigger another maintenance. New-type selection also ignores maintenance time if the remaining horizon is too short for that robot to exhaust its work budget, making the default choice better for short tails.

```python
def rule(ctx):
    avail = ctx.available
    n = len(avail)
    t = ctx.t
    types = ctx.types
    robots = ctx.robots

    # Count robots that are already down for maintenance or otherwise long unavailable.
    long_down = 0
    for r in robots:
        if r.ready > t:
            if r.duties_left <= 0:
                long_down += 1
            else:
                typ = types[r.type] if r.type < len(types) else None
                if typ is not None:
                    normal = typ["charge_time"] + typ["out_travel_time"] + typ["return_travel_time"] + 5.0
                    if r.ready > t + normal:
                        long_down += 1
                else:
                    if r.ready > t + 10.0:
                        long_down += 1

    if n > 0:
        min_count = min(r.count for r in avail)

        if long_down > 0:
            def rkey(r):
                # Avoid triggering maintenance on this duty while coverage is already tight.
                tier = 0 if r.duties_left > 1 else 1
                return (tier, r.count, r.hours, -r.duties_left, -r.budget, r.idx)
        else:
            def rkey(r):
                # Original balanced rule: use urgent maintenance while cover exists,
                # but do not grossly overwork one robot.
                if r.duties_left <= 1 and n >= 2 and r.count <= min_count + 2:
                    tier = 0
                    maint_key = r.duties_left
                else:
                    tier = 1
                    maint_key = -r.duties_left
                return (tier, r.count, r.hours, maint_key, -r.budget, r.idx)

        ordered = sorted(avail, key=rkey)
        return [("reuse", r) for r in ordered]

    # No robot is available: choose the most sustainable new type.
    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        gene = ctx.gene_type
        if gene is not None and 0 <= gene < len(types) and types[gene] is not None:
            return [("new", gene)]
        for k in range(len(types)):
            if types[k] is not None:
                return [("new", k)]
        return [("new", 0)]

    def type_key(k):
        typ = types[k]
        cm = typ.get('continue_max_work', 0) or 0
        sw = typ.get('single_work_time', 1) or 1
        if sw <= 0:
            sw = 1
        duties_per_cycle = cm / sw if sw else 1

        out = typ.get('out_travel_time', 0) or 0
        ret = typ.get('return_travel_time', 0) or 0
        ct = typ.get('charge_time', 0) or 0
        mt = typ.get('maintenance_time', 0) or 0
        wt = typ.get('work_time', 1) or 1

        # If the remaining horizon is too short for this robot to reach maintenance,
        # do not penalize its long maintenance time.
        cycle_time = wt + out + ret + ct
        if cycle_time <= 0:
            cycle_time = 1
        expected_duties = ctx.remaining / cycle_time
        effective_mt = mt if expected_duties * sw >= cm else 0.0

        overhead = (out + ret + ct) * duties_per_cycle
        denom = cm + overhead + effective_mt
        avail_frac = cm / denom if denom > 0 else 0.0

        fit = 0 if wt <= ctx.remaining else 1
        return (fit, -avail_frac, -ctx.left[k], k)

    valid_sorted = sorted(valid, key=type_key)
    return [("new", k) for k in valid_sorted]
```

The rule uses a horizon-aware maintenance-window strategy rather than plain load balancing: it ranks available robots by projected count/hour balance, but gives priority to robots whose maintenance is due only when maintenance can actually finish and leave useful work before the horizon; near the end or when resetting would strand a robot, it defers maintenance to a fresher robot. New-robot types are ordered by the amortized fraction of useful duty time they can supply over the actual remaining horizon, including their maintenance cycle.

```python
def rule(ctx):
    types = ctx.types
