    remaining = ctx.remaining

    total_wt = 0.0
    ntypes = 0
    for typ in types:
        if typ is not None:
            wt = typ.get("work_time", 10) or 10.0
            total_wt += wt
            ntypes += 1
    avg_wt = total_wt / ntypes if ntypes > 0 else 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    min_load_all = None
    for r in robots:
        load = r.count + r.hours / avg_wt
        if min_load_all is None or load < min_load_all:
            min_load_all = load
    if min_load_all is None:
        min_load_all = 0.0

    n_avail = len(avail)
    actions = []

    if n_avail > 0:
        def rkey(r):
            typ = types[r.type] if 0 <= r.type < len(types) else None
            if typ is None:
                wt = avg_wt
                ret = 0.0
                ct = 0.0
                mt = 0.0
            else:
                wt = typ.get("work_time", avg_wt) or avg_wt
                ret = typ.get("return_travel_time", 0) or 0.0
                ct = typ.get("charge_time", 0) or 0.0
                mt = typ.get("maintenance_time", 0) or 0.0

            proj_load = (r.count + 1) + (r.hours + wt) / avg_wt
            trigger = r.duties_left <= 1
            tier = 1

            if trigger:
                post_maint_ready = t + wt + ret + ct + mt
                useful_reset = (post_maint_ready + wt <= T)
                current_load = r.count + r.hours / avg_wt

                if useful_reset and n_avail >= 2 and current_load <= min_load_all + 1.5:
                    tier = 0
                elif not useful_reset:
                    tier = 2

            return (tier, proj_load, r.count, r.hours, -r.duties_left, r.idx)

        ordered = sorted(avail, key=rkey)
        actions = [("reuse", r) for r in ordered]

    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    gene = ctx.gene_type

    if valid:
        def tkey(k):
            typ = types[k]
            wt = typ.get("work_time", 10) or 10.0
            sw = typ.get("single_work_time", wt) or wt
            cm = typ.get("continue_max_work", 0) or 0.0
            out = typ.get("out_travel_time", 0) or 0.0
            ret = typ.get("return_travel_time", 0) or 0.0
            ct = typ.get("charge_time", 0) or 0.0
            mt = typ.get("maintenance_time", 0) or 0.0

            if sw <= 0:
