            duties_before_maint = cm / sw if sw > 0 else 1.0
            if duties_before_maint < 1.0:
                duties_before_maint = 1.0

            cycle = out + wt + ret + ct
            if cycle <= 0:
                cycle = wt

            H = remaining
            if H <= 0:
                frac = 1.0
            elif H <= duties_before_maint * cycle:
                frac = wt / cycle
            else:
                period = duties_before_maint * cycle + mt
                if H < period:
                    frac = (duties_before_maint * wt) / H
                else:
                    frac = (duties_before_maint * wt) / period if period > 0 else 0.0

            fit = 0 if wt <= H + 1e-9 else 1
            bonus = 0.02 if k == gene else 0.0
            return (fit, -(frac + bonus), mt, cycle, -ctx.left[k], k)

        valid_sorted = sorted(valid, key=tkey)
        for k in valid_sorted:
            actions.append(("new", k))
    else:
        if gene is not None and 0 <= gene < len(types) and types[gene] is not None:
            actions.append(("new", gene))
        else:
            for k in range(len(types)):
                if types[k] is not None:
                    actions.append(("new", k))
                    break
            else:
                actions.append(("new", 0))

