```python
def rule(ctx):
    types = ctx.types
    robots = ctx.robots
    remaining = ctx.remaining
    N = len(robots) if len(robots) > 0 else 1

    opened_types = set()
    for r in robots:
        opened_types.add(r.type)

    coins = []
    possible_wts = []
    for k in range(len(types)):
        typ = types[k]
        if typ is not None and (ctx.left[k] > 0 or k in opened_types):
            wt = typ.get('work_time', 10) or 10
            if wt > 0:
                coins.append(wt)
                possible_wts.append(wt)

    def feasible(rem, coin_list):
        if rem == 0:
            return True
        if rem < 0:
            return False
        cl = [c for c in coin_list if c > 0]
        if not cl:
            return False
        g = 0
        for c in cl:
            g = math.gcd(g, c)
        if rem % g != 0:
            return False
        minc = min(cl)
        maxc = max(cl)
        if rem < minc:
            return False
        if rem >= minc * maxc:
            return True
        reach = [False] * (rem + 1)
        reach[0] = True
        for c in cl:
            for s in range(c, rem + 1):
                if reach[s - c]:
                    reach[s] = True
        return reach[rem]

    if possible_wts:
        avg_wt = sum(possible_wts) / float(len(possible_wts))
    else:
        total_wt = 0.0
        num_wt = 0
        for typ in types:
            if typ is not None:
                wt = typ.get('work_time', 10) or 10
                total_wt += wt
                num_wt += 1
        avg_wt = total_wt / float(num_wt) if num_wt > 0 else 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    avail = ctx.available
    if avail:
        n = len(avail)
        min_count = min(r.count for r in avail)

        S_q = 0.0
        for r in robots:
            typ = types[r.type] or {}
            wt = typ.get('work_time', 10) or 10
            S_q += r.count + r.hours / avg_wt
        mean_q = S_q / float(N)

        M = 0
        S_m = 0.0
        SS_m = 0.0
        for r in robots:
            fm = r.first_maint
            if fm is not None:
                M += 1
                S_m += fm
                SS_m += fm * fm
        mean_m = S_m / float(M) if M > 0 else 0.0

        need_cap = False
        for r in avail:
            if r.duties_left <= 1 and n >= 2 and r.count <= min_count + 2:
                need_cap = True
                break
        if need_cap:
            slack = ctx.capacity - remaining
        else:
            slack = 0.0
        buffer = max(2.0 * avg_wt, 20.0)

        def rkey(r):
            typ = types[r.type] or {}
            wt = typ.get('work_time', 10) or 10
            out = typ.get('out_travel_time', 0) or 0
            ret = typ.get('return_travel_time', 0) or 0
            mt = typ.get('maintenance_time', 0) or 0

            rem_after = remaining - wt
            if wt > remaining + 1e-9:
                fit_tier = 2
            elif feasible(rem_after, coins):
                fit_tier = 0
            else:
                fit_tier = 1

            q = r.count + r.hours / avg_wt
            dq = 1.0 + wt / avg_wt
            if N > 1:
                balance = 2.0 * dq * (q - mean_q) + dq * dq * (1.0 - 1.0 / float(N))
            else:
                balance = 0.0

            maint_pen = 0.0
            if r.first_maint is None and r.duties_left <= 1 and M > 0:
                x = ctx.t + out + wt + ret
                diff = (x - mean_m) / (ctx.T if ctx.T > 0 else 1.0)
                maint_pen = 4.0 * (M / float(M + 1)) * diff * diff

            urgent = False
            if r.duties_left <= 1 and n >= 2 and r.count <= min_count + 2:
                if slack < buffer:
                    urgent = True

            tier = (fit_tier, 0 if urgent else 1)

            return (tier, balance + maint_pen, r.count, r.hours,
                    -r.duties_left, -r.budget,
                    r.ready if r.ready is not None else 0.0, r.idx)

        ordered = sorted(avail, key=rkey)
        return [("reuse", r) for r in ordered]

    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        return [("new", ctx.gene_type)]

    def tkey(k):
        typ = types[k]
        wt = typ.get('work_time', 10) or 10
        out = typ.get('out_travel_time', 0) or 0
        ret = typ.get('return_travel_time', 0) or 0
        ct = typ.get('charge_time', 0) or 0
        mt = typ.get('maintenance_time', 0) or 0
        cm = typ.get('continue_max_work', 0) or 0
        sw = typ.get('single_work_time', wt) or wt
        if sw <= 0:
            sw = 1.0

        duties_before_maint = cm / sw if cm > 0 else 1.0
        if duties_before_maint < 1.0:
            duties_before_maint = 1.0

        cycle = out + wt + ret + ct
        if cycle <= 0:
            cycle = wt if wt > 0 else 1.0

        if remaining <= duties_before_maint * wt:
            frac = wt / cycle
        else:
            frac = wt / (cycle + mt / duties_before_maint)

        new_coins = list(coins)
        if wt not in new_coins:
            new_coins.append(wt)

        rem_after = remaining - wt
        if wt > remaining + 1e-9:
            fit_tier = 2
        elif feasible(rem_after, new_coins):
            fit_tier = 0
        else:
            fit_tier = 1

        gene_bonus = 0.03 if k == ctx.gene_type else 0.0
        return (fit_tier, -(frac + gene_bonus), -ctx.left[k], k)

    valid_sorted = sorted(valid, key=tkey)
    return [("new", k) for k in valid_sorted]
