The new rule uses a **maintenance-pipeline** bias rather than pure load balancing: it balances equivalent duty load (counts plus normalized hours), but when a robot is one duty away from maintenance it triggers the robot whose maintenance takes longest first, while avoiding extra maintenance triggers if another long maintenance is already underway. When no robot is available, it chooses new types by effective covered duty-hours per calendar hour, with a preference for types already opened to save tool resources.

```python
def rule(ctx):
    avail = ctx.available
    robots = ctx.robots
    types = ctx.types
    t = ctx.t
    remaining = ctx.remaining

    def type_info(typ):
        if typ is None:
            return (10.0, 0.0, 0.0, 0.0, 0.0, 10.0, 1.0)
        wt = typ.get("work_time", 10.0)
        if wt is None or wt <= 0:
            wt = 10.0
        out = typ.get("out_travel_time", 0.0) or 0.0
        ret = typ.get("return_travel_time", 0.0) or 0.0
        ct = typ.get("charge_time", 0.0) or 0.0
        mt = typ.get("maintenance_time", 0.0) or 0.0
        sw = typ.get("single_work_time", wt)
        if sw is None or sw <= 0:
            sw = wt
        cm = typ.get("continue_max_work", 0.0) or 0.0
        duties = cm / sw if sw > 0 else 1.0
        if duties <= 0:
            duties = 1.0
        cycle = wt + out + ret + ct
        return (wt, out, ret, ct, mt, cycle, duties)

    # Average duty length, used to compare duty counts and duty hours together.
    total_wt = 0.0
    num_r = 0
    for r in robots:
        typ = types[r.type] if r.type < len(types) else None
        wt = type_info(typ)[0]
        total_wt += wt
        num_r += 1
    target = total_wt / num_r if num_r > 0 else 10.0
    if target <= 0:
        target = 10.0

    # Count robots currently in long maintenance rather than short charging.
    long_down = 0
    for r in robots:
        if r.ready > t:
            typ = types[r.type] if r.type < len(types) else None
            wt, out, ret, ct, mt, cycle, duties = type_info(typ)
            if r.duties_left <= 0 or r.ready > t + cycle + 1.0:
                long_down += 1

    def load_of(r):
        return r.count + (r.hours / target if target > 0 else 0.0)

    if avail:
        n = len(avail)
        loads = {}
        min_load = None
        for r in avail:
            v = load_of(r)
            loads[r.idx] = v
            if min_load is None or v < min_load:
                min_load = v

        # If no maintenance is currently active, consider starting one early
        # to stagger long maintenance events, preferring the longest downtime.
        proactive = None
        if n >= 2 and long_down == 0:
            best_key = None
            for r in avail:
                if r.duties_left <= 1:
                    typ = types[r.type] if r.type < len(types) else None
                    wt, out, ret, ct, mt, cycle, duties = type_info(typ)
                    if remaining <= cycle + mt:
                        continue
                    lv = loads[r.idx]
                    # Do not send a heavily over-used robot just to start maintenance.
                    if lv <= min_load + 2.5:
                        key = (-mt, lv, r.duties_left, -r.budget, r.idx)
                        if best_key is None or key < best_key:
                            best_key = key
                            proactive = r

        def normal_key(r):
            typ = types[r.type] if r.type < len(types) else None
            wt, out, ret, ct, mt, cycle, duties = type_info(typ)
            lv = loads[r.idx]
            pen = 0.0

            if r.duties_left <= 1:
                if remaining > cycle + mt:
                    if long_down > 0:
                        # Another long maintenance is already active: avoid adding
                        # another unless load balance strongly favors it.
                        pen += 1.8 - mt / 150.0
                    else:
                        pen += 0.3
                else:
                    # It would not return before the horizon ends.
                    pen += 2.5
            elif r.duties_left == 2 and long_down > 0:
                pen += 0.3

            return (lv + pen, r.duties_left, -r.budget, r.idx)

        ordered = sorted(avail, key=normal_key)

        if proactive is not None:
            result = [("reuse", proactive)]
            for r in ordered:
                if r is not proactive:
                    result.append(("reuse", r))
            return result

        return [("reuse", r) for r in ordered]

    # No robot is available now: rank new robot types.
    existing = set()
    for r in robots:
        existing.add(r.type)

    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    gene = ctx.gene_type
    if not valid:
        if gene is not None and gene >= 0 and gene < len(types) and types[gene] is not None:
            return [("new", gene)]
        for k in range(len(types)):
            if types[k] is not None:
                return [("new", k)]
        return [("new", 0)]

    cap = ctx.capacity
    tight = cap is not None and cap < remaining

    def type_key(k):
        typ = types[k]
        wt, out, ret, ct, mt, cycle, duties = type_info(typ)

        full_cycle = wt + out + ret + ct + (mt / duties if duties > 0 else mt)
        eff = wt / full_cycle if full_cycle > 0 else 0.0

        fit = 0 if wt <= remaining + 0.01 else 1
        existing_bonus = 0.22 if k in existing else 0.0
        gene_bonus = 0.03 if gene is not None and k == gene else 0.0

        # Under immediate shortage, a short recovery cycle is slightly better.
        quick_bonus = 0.0
        if long_down > 0:
            quick_bonus = -0.06 * ((wt + out + ret + ct + mt / max(duties, 1.0)) / 10.0)

        # If capacity is already sufficient, prefer existing types even more.
        if not tight and k in existing:
            existing_bonus += 0.05

        score = eff + existing_bonus + gene_bonus + quick_bonus
        return (fit, -score, -ctx.left[k], k)

    valid_sorted = sorted(valid, key=type_key)
    return [("new", k) for k in valid_sorted]
