The rule keeps Rule 2’s normalized load balancing as the main reuse priority, then adds maintenance-awareness from Rule 1: when a robot is about to hit maintenance it is deliberately used early only if it can return before the horizon ends, it is not too far ahead in load, and doing so will not create simultaneous maintenance. New-robot type choice uses Rule 2’s efficiency/existing-type bias with a small gene-type preference and a fit check that avoids leaving an uncoverably short tail.

```python
def rule(ctx):
    t = ctx.t
    remaining = ctx.remaining
    types = ctx.types
    robots = ctx.robots
    avail = ctx.available
    gene = ctx.gene_type

    # Average duty length of opened robots, for normalizing duty hours.
    total_wt = 0.0
    num_r = 0
    for r in robots:
        typ = types[r.type] if r.type < len(types) else None
        if typ is not None:
            wt = typ["work_time"]
            if wt is None or wt <= 0:
                wt = 10.0
            total_wt += wt
            num_r += 1
    avg_work = total_wt / num_r if num_r > 0 else 10.0

    # Count robots that are unavailable much longer than a normal charge/travel cycle.
    active_maint = 0
    for r in robots:
        if r.ready > t:
            if r.duties_left <= 0:
                active_maint += 1
            else:
                typ = types[r.type] if r.type < len(types) else None
                if typ is not None:
                    wt = typ["work_time"] or 10.0
                    normal = ((typ["charge_time"] or 0.0) +
                              (typ["out_travel_time"] or 0.0) +
                              (typ["return_travel_time"] or 0.0) +
                              wt + 5.0)
                    if r.ready > t + normal:
                        active_maint += 1
                else:
                    if r.ready > t + 15.0:
                        active_maint += 1

    if avail:
        n = len(avail)
        load = {}
        for r in avail:
            load[r.idx] = r.count + (r.hours / avg_work if avg_work > 0 else 0.0)
        min_load = min(load.values())

        def key(r):
            sc = load[r.idx]
            typ = types[r.type] if r.type < len(types) else None
            triggers = r.duties_left <= 1

            # Proactive maintenance: use a near-maintenance robot early only
            # if it can return and is not too far ahead in balanced load.
            if triggers and n >= 2 and typ is not None:
                mt = typ["maintenance_time"] or 0.0
                wt = typ["work_time"] or 10.0
                if remaining > mt + wt:
                    coeff = 1.0 + (wt / avg_work if avg_work > 0 else 0.0)
                    slack = 2.0 * coeff if active_maint == 0 else 0.0
                    if sc <= min_load + slack:
                        return (0, sc, r.duties_left, -r.budget, r.idx)

            # Otherwise balance count + normalized hours, then avoid
            # triggering maintenance, then prefer more remaining budget.
            return (1, sc, -r.duties_left, -r.budget, r.idx)

        ordered = sorted(avail, key=key)
        return [("reuse", r) for r in ordered]

    # No robot is available: choose the new robot type.
    existing = set()
    for r in robots:
        existing.add(r.type)

    valid = []
    for k in range(len(types)):
        if types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        if gene is not None and 0 <= gene < len(types) and types[gene] is not None:
            return [("new", gene)]
        for k in range(len(types)):
            if types[k] is not None:
                return [("new", k)]
        return [("new", 0)]

    # Smallest duty length that can still be used, including opened types.
    min_wt = None
    for k in range(len(types)):
        typ = types[k]
        if typ is not None and (k in existing or ctx.left[k] > 0):
            wt = typ["work_time"]
            if wt is None or wt <= 0:
                wt = 10.0
            if min_wt is None or wt < min_wt:
                min_wt = wt
    if min_wt is None or min_wt <= 0:
        min_wt = 1.0

    def type_key(k):
        typ = types[k]
        cm = typ["continue_max_work"] or 0.0
        sw = typ["single_work_time"] or 1.0
        if sw <= 0:
            sw = 1.0
        duties = cm / sw if sw else 1.0

        out = typ["out_travel_time"] or 0.0
        ret = typ["return_travel_time"] or 0.0
        ct = typ["charge_time"] or 0.0
        mt = typ["maintenance_time"] or 0.0
        wt = typ["work_time"] or 1.0

        overhead = (out + ret + ct) * duties
        denom = cm + overhead + mt
        avail_frac = cm / denom if denom > 0 else 0.0

        # Fit to remaining horizon: exact fit, then fitting without leaving
        # an uncoverably small remainder, then any fit, then overshoot.
        if wt > remaining + 1e-9:
            fit = 3
        else:
            rem2 = remaining - wt
            if rem2 < 1e-9:
                fit = 0
            elif rem2 < min_wt - 1e-9:
                fit = 2
            else:
                fit = 1

        existing_bonus = 0.2 if k in existing else 0.0
        gene_bonus = 0.05 if k == gene else 0.0

        return (fit, -avail_frac - existing_bonus - gene_bonus, -ctx.left[k], k)

    valid_sorted = sorted(valid, key=type_key)
    return [("new", k) for k in valid_sorted]
