        denom = work_per_cycle + overhead + mt_eff
        cycle_eff = work_per_cycle / denom if denom > 0 else 0.0

        bonus = 0.05 if k == ctx.gene_type else 0.0

        if wt <= rem + 1e-9:
            return (0, -cycle_eff - bonus, -wt, -ctx.left[k], k)
        return (1, wt, -cycle_eff - bonus, -ctx.left[k], k)

    valid_sorted = sorted(valid, key=type_key)
    return [("new", k) for k in valid_sorted]
```

The improved rule replaces the count-only priority with a marginal-variance score that jointly balances duty counts and duty hours, normalized by the average work time of opened robots. It uses this combined load to decide when to trigger maintenance for urgent robots, while preserving the capacity-aware thresholds from the original rule. New robot type selection retains cycle-efficiency and remaining-horizon fitting, but adds a small bonus for types already in use to encourage uniform duty lengths and easier count/hour balancing.

```python
def rule(ctx):
    avail = ctx.available
    n = len(avail)
    T = ctx.T
    t = ctx.t
    rem = ctx.remaining
    types = ctx.types

    # Reference work time for normalizing duty hours
    total_wt = 0.0
    num = 0
    for r in ctx.robots:
        typ = types[r.type] if r.type < len(types) and types[r.type] is not None else None
        if typ is not None:
            total_wt += typ.get('work_time', 10) or 10
            num += 1
    if num > 0:
        avg_wt = total_wt / num
    else:
        sum_wt = 0.0
        cnt = 0
        for k in range(len(types)):
            typ = types[k]
            if typ is not None:
                sum_wt += typ.get('work_time', 10) or 10
                cnt += 1
        avg_wt = sum_wt / cnt if cnt > 0 else 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    if n > 0:
        min_load = None
        for r in avail:
            typ = types[r.type] if r.type < len(types) and types[r.type] is not None else {}
            load = 0.5 * r.count + 0.5 * (r.hours / avg_wt)
            if min_load is None or load < min_load:
                min_load = load
        if min_load is None:
            min_load = 0.0

        need_cap = False
        for r in avail:
            if r.duties_left <= 1:
                need_cap = True
                break
        cap = ctx.capacity if need_cap and n > 1 else 0.0

        def rkey(r):
            typ = types[r.type] if r.type < len(types) and types[r.type] is not None else {}
            wt = typ.get('work_time', 10) or 10
            ret = typ.get('return_travel_time', 0) or 0
            mt = typ.get('maintenance_time', 0) or 0

            finish = t + wt + ret + mt
            can_return = finish <= T + 1e-9
            urgent = r.duties_left <= 1
            load = 0.5 * r.count + 0.5 * (r.hours / avg_wt)

            trigger = False
            defer = False
            if urgent:
                if n == 1:
                    trigger = True
                else:
                    thresh = 2.0
                    if not can_return:
                        thresh = 1.0
                        if cap < rem * 1.15:
                            thresh = 0.0
                    if load <= min_load + thresh + 1e-9:
                        trigger = True
                    else:
                        defer = True

            if trigger:
                tier = 0
            elif defer:
                tier = 2
            else:
                tier = 1

            delta_c = 2.0 * r.count + 1.0
            delta_h = ((r.hours + wt) ** 2 - r.hours ** 2) / (avg_wt ** 2)
            score = delta_c + delta_h

            maint_tie = -mt if tier == 0 else 0.0
            return (tier, score, maint_tie, r.count, r.hours, -r.budget, r.idx)

        ordered = sorted(avail, key=rkey)
        return [("reuse", r) for r in ordered]

    valid = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        return [("new", ctx.gene_type)]

    type_counts = {}
    for r in ctx.robots:
        type_counts[r.type] = type_counts.get(r.type, 0) + 1

    def type_key(k):
        typ = ctx.types[k]
        cm = typ.get('continue_max_work', 0) or 0
        sw = typ.get('single_work_time', 1) or 1
        if sw <= 0:
            sw = 1
        wt = typ.get('work_time', 10) or 10
        out = typ.get('out_travel_time', 0) or 0
        ret = typ.get('return_travel_time', 0) or 0
        ct = typ.get('charge_time', 0) or 0
        mt = typ.get('maintenance_time', 0) or 0

        duties = cm / sw if sw else 1.0
        work_per_cycle = duties * wt
        overhead = duties * (out + ret + ct)
        mt_eff = mt if rem > work_per_cycle + 1e-9 else 0.0
        denom = work_per_cycle + overhead + mt_eff
        cycle_eff = work_per_cycle / denom if denom > 0 else 0.0

        same = type_counts.get(k, 0)
        uniform_bonus = 0.01 * same
        bonus = 0.05 if k == ctx.gene_type else 0.0
        total_bonus = bonus + uniform_bonus

        if wt <= rem + 1e-9:
            return (0, - (cycle_eff + total_bonus), -wt, -ctx.left[k], k)
        else:
            return (1, wt, - (cycle_eff + total_bonus), -ctx.left[k], k)

    valid_sorted = sorted(valid, key=type_key)
    return [("new", k) for k in valid_sorted]
