The rule keeps the existing count/hour balancing but makes maintenance timing horizon-aware: a robot with one duty left is promoted only if its maintenance can finish and it is not too far ahead in duties; near-horizon “last duty” uses are otherwise deferred. It also lightly favors robots whose first maintenance has not yet occurred, and improves new-robot type choice by using an adaptive work-fraction estimate (ignoring maintenance when the horizon is too short to trigger it) and by penalizing duty lengths that overshoot the remaining horizon.

```python
def rule(ctx):
    avail = ctx.available

    if avail:
        n = len(avail)

        sum_wt = 0.0
        for r in avail:
            typ = ctx.types[r.type] or {}
            wt = typ.get('work_time', 10.0) or 10.0
            if wt <= 0:
                wt = 10.0
            sum_wt += wt
        avg_wt = sum_wt / n if n > 0 else 10.0
        if avg_wt <= 0:
            avg_wt = 10.0

        min_count = min(r.count for r in avail)

        def rkey(r):
            typ = ctx.types[r.type] or {}
            wt = typ.get('work_time', 10.0) or 10.0
            if wt <= 0:
                wt = 10.0
            mt = typ.get('maintenance_time', 0.0) or 0.0

            pc = r.count + 1
            ph = r.hours + wt
            balance = pc + ph / avg_wt

            fit = 0 if wt <= ctx.remaining + 1e-9 else 1
            rem_after = ctx.remaining - wt
            returns = rem_after >= mt + wt - 1e-9
            near = r.duties_left <= 1

            if near:
                if returns and r.count <= min_count + 2:
                    tier = 0
                elif (not returns) and r.count > min_count:
                    tier = 3
                else:
                    tier = 1
            else:
                tier = 1

            first_tier = 0 if (r.first_maint is None and r.count <= min_count + 1) else 1

            return (fit, tier, first_tier, balance, r.count, r.hours,
                    -r.duties_left, -r.budget, r.idx)

        ordered = sorted(avail, key=rkey)
        return [("reuse", r) for r in ordered]

    valid = []
    for k in range(len(ctx.types)):
        typ = ctx.types[k]
        if typ is not None and ctx.left[k] > 0:
            valid.append(k)

    if not valid:
        return [("new", ctx.gene_type)]

    def tkey(k):
        typ = ctx.types[k]
        wt = typ.get('work_time', 10.0) or 10.0
        if wt <= 0:
            wt = 10.0
        out = typ.get('out_travel_time', 0.0) or 0.0
        ret = typ.get('return_travel_time', 0.0) or 0.0
        ct = typ.get('charge_time', 0.0) or 0.0
        mt = typ.get('maintenance_time', 0.0) or 0.0
        cm = typ.get('continue_max_work', 0.0) or 0.0
        sw = typ.get('single_work_time', wt) or wt
        if sw <= 0:
            sw = wt

        if cm <= 0:
            duties = 1e6
        else:
            duties = cm / sw
            if duties < 1.0:
                duties = 1.0

        cycle = out + wt + ret + ct
        if cycle <= 0:
            cycle = wt

        time_to_maint = duties * cycle
        if ctx.remaining <= time_to_maint + 1e-9:
            frac = wt / cycle
        else:
            denom = time_to_maint + mt
            frac = (duties * wt) / denom if denom > 0 else 0.0

        overshoot = wt - ctx.remaining
        if overshoot < 0.0:
            overshoot = 0.0
        fit = 0 if overshoot <= 1e-9 else 1

        bonus = 0.05 if k == ctx.gene_type else 0.0
        return (fit, overshoot, -(frac + bonus), -ctx.left[k], mt, k)

    valid_sorted = sorted(valid, key=tkey)
    return [("new", k) for k in valid_sorted]
```

I use a continuous maintenance-pressure score rather than tiered triggers: when few robots are opened, the rule aggressively drives the lowest-budget robot toward maintenance to create staggered maintenance phases; once more robots exist, the same score gradually shifts toward load balancing, with pressure moderated by the estimated remaining capacity. New robot types are ordered by horizon-aware work efficiency and similarity to existing types.

```python
def rule(ctx):
    avail = ctx.available
