        elif cap_ratio < 1.15:
            alpha = 1.6
        elif cap_ratio < 1.35:
            alpha = 1.2
        elif cap_ratio < 1.7:
            alpha = 0.8
        else:
            alpha = 0.3
        if n_opened == 3:
            alpha = min(1.9, alpha + 0.2)

    def key(r):
        typ = types[r.type] if r.type < len(types) else None
        if typ is not None:
            wt = typ.get('work_time', 10) or 10
        else:
            wt = 10

        d = r.duties_left
        load = r.count + r.hours / avg_wt
        fit = 0 if wt <= rem + 1e-9 else 1
        score = alpha * d + load
        return (fit, score, r.count, r.hours, -d, -r.budget, r.idx)

